    Props (p): id, title, lead, badge, posts, labels, action, layout, cols, mediaSide, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_badge = ($p['badge'] ?? '')}
{var $v_posts = ($p['posts'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_action = ($p['action'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'intro')}
{var $v_cols = ($p['cols'] ?? '3')}
{var $v_mediaSide = ($p['mediaSide'] ?? 'start')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{if ui_t(ui_eq($v_layout, 'intro'))}
  {capture $f_2}
    {capture $c_3}
      {foreach ui_l($v_posts) as $v_p}
        {var $v_i = $iterator->counter0}
        {if ui_t(ui_lt($v_i, 4))}
          {=ui_include('blocks/post-mini-card.latte', ['p' => ['p' => $v_p, 'labels' => $v_labels]])|noescape}
        {/if}
      {/foreach}
    {/capture}
    {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'grid grid-cols-1 gap-4 sm:grid-cols-2'], 'children' => $c_3])|noescape}
  {/capture}
  {capture $c_4}
    {capture $c_1}
      {=ui_text(ui_get($v_action, ['label']))}
      {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'arrow-right', 'Size' => 16]])|noescape}
    {/capture}
    {=ui_include('ui/link/link.latte', ['p' => ['Href' => ui_s(ui_get($v_action, ['href'])), 'Size' => 'sm', 'Attrs' => ui_attrs(['data-testid', 'section-action'])], 'children' => $c_1])|noescape}
  {/capture}
  {=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'heading' => ['badge' => $v_badge], 'tone' => $v_tone, 'layout' => 'split', 'media' => ['show' => true, 'side' => $v_mediaSide], 'landmarkLabel' => $v_landmarkLabel, 'aside' => $f_2], 'children' => $c_4])|noescape}
{elseif ui_t(ui_eq($v_layout, 'featured'))}
  {capture $f_5}
    {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => '4/3']])|noescape}
  {/capture}
  {capture $c_6}
    {foreach ui_l($v_posts) as $v_p}
      {var $v_i = $iterator->counter0}
      {if ui_t(ui_lt($v_i, 1))}
        {=ui_include('blocks/post-feature.latte', ['p' => ['p' => $v_p, 'labels' => $v_labels]])|noescape}
      {/if}
    {/foreach}
  {/capture}
  {=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'heading' => ['badge' => $v_badge], 'tone' => $v_tone, 'layout' => 'split', 'media' => ['show' => true, 'side' => $v_mediaSide], 'landmarkLabel' => $v_landmarkLabel, 'aside' => $f_5], 'children' => $c_6])|noescape}
{else}
  {capture $c_8}
    {capture $c_7}
      {foreach ui_l($v_posts) as $v_p}
        {var $v_i = $iterator->counter0}
        {if ui_t(ui_lt($v_i, (ui_t(ui_eq($v_cols, '2')) ? 2 : 3)))}
          {=ui_include('blocks/post-overlay-card.latte', ['p' => ['p' => $v_p, 'labels' => $v_labels, 'ratio' => (ui_t(ui_eq($v_cols, '2')) ? '16/9' : '4/3')]])|noescape}
        {/if}
      {/foreach}
    {/capture}
    {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s((ui_t(ui_eq($v_cols, '2')) ? 'grid grid-cols-1 gap-6 md:grid-cols-2' : 'grid grid-cols-1 gap-6 md:grid-cols-3'))], 'children' => $c_7])|noescape}
  {/capture}
  {=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'heading' => ['badge' => $v_badge], 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_8])|noescape}
{/if}
